#include <print>
#include <vector>

int main() {
    std::vector<int> v = {3, 1, 4, 2};

    for (size_t j = 0; j + 1 < v.size(); j++) {
        if (v[j] > v[j + 1]) {
            int t = v[j];
            v[j] = v[j + 1];
            v[j + 1] = t;
        }
        std::println("j = {} 之后: {}", j, v);   // 纸上抄的：1 3 4 2、1 3 4 2、1 3 2 4，一轮后 4 站到最后面
    }

    return 0;
}

